import csv

def analyze(f):
    print('='*10, f)
    try:
        with open(f) as fh:
            rows = list(csv.reader(fh))
    except Exception as ex:
        print('ERR', ex); return
    if not rows:
        print('empty'); return
    hdr = rows[0]
    print('header:', hdr, '| n rows:', len(rows)-1)
    for row in rows[1:4]:
        print(row)
    low = [h.lower() for h in hdr]
    def col(*names):
        for n in names:
            if n in low: return low.index(n)
        return None
    yi = col('year'); ai = col('actual','actual_claims','actuals','act')
    ei = col('expected','expected_claims','expecteds','exp')
    si = col('segment','age_band','age','age_gender','diagnosis','band','duration')
    gi = col('gender','sex')
    if None not in (yi,ai,ei) and (si is not None or gi is not None):
        agg = {}
        for row in rows[1:]:
            try:
                y=int(row[yi]); a=float(row[ai]); e=float(row[ei])
            except Exception:
                continue
            key = (row[si] if si is not None else '?', row[gi] if gi is not None else '?')
            d = agg.setdefault(key,[0.0,0.0,0.0,0.0])
            if y<=2016: d[0]+=a; d[1]+=e
            else: d[2]+=a; d[3]+=e
        print('segment | A/E 2015-16 | A/E 2017-24 | diff | exp1516 | exp1724')
        for k,d in sorted(agg.items()):
            ae1 = d[0]/d[1] if d[1] else float('nan')
            ae2 = d[2]/d[3] if d[3] else float('nan')
            print(k, round(ae1,3), round(ae2,3), round(ae1-ae2,3), round(d[1]), round(d[3]))

for f in ['ae_death_age_gender.csv','ae_ci_age_gender.csv','ae_ip_age_gender.csv','ae_tpd_age_gender.csv','ae_ip_termination_by_month.csv']:
    analyze(f)
